t.script:
        /* ── inline glue identical to standalone calculator.html ── */
        (function(){
          /* All calculation logic is in calculator.js (loaded via assets).
             This inline block wires up the DOM and calls window.runCalculation
             if the module exports it, otherwise duplicates the minimal logic. */

          const ARCH={
            mvp_spaghetti:       {label:'MVP (Spaghetti Code)',debtRatio:.80,velocityPenalty:.65,maintenanceCost:.35,bugRate:.45,securityRisk:.75,scalabilityLimit:2,  refactorMonths:4,  ci_cd:false,testCoverage:.05},
            early_structured:    {label:'Early Stage',         debtRatio:.55,velocityPenalty:.45,maintenanceCost:.25,bugRate:.30,securityRisk:.55,scalabilityLimit:5,  refactorMonths:3,  ci_cd:false,testCoverage:.20},
            scaling_modular:     {label:'Scaling/Modular',     debtRatio:.25,velocityPenalty:.20,maintenanceCost:.15,bugRate:.15,securityRisk:.30,scalabilityLimit:20, refactorMonths:1.5,ci_cd:true, testCoverage:.60},
            mature_best_practice:{label:'Mature',              debtRatio:.08,velocityPenalty:.05,maintenanceCost:.08,bugRate:.05,securityRisk:.10,scalabilityLimit:100,refactorMonths:.5, ci_cd:true, testCoverage:.85},
          };
          const STAGES={
            seed:         {label:'Seed',         fundingPressure:.90,marketWindowMonths:6, competitorRisk:.80,valuationMultiplier:3, urgencyMult:2.0},
            pre_series_a: {label:'Pre-Series A', fundingPressure:.75,marketWindowMonths:9, competitorRisk:.65,valuationMultiplier:5, urgencyMult:1.7},
            series_a:     {label:'Series A',     fundingPressure:.60,marketWindowMonths:12,competitorRisk:.50,valuationMultiplier:8, urgencyMult:1.4},
            series_b_plus:{label:'Series B+',    fundingPressure:.40,marketWindowMonths:18,competitorRisk:.35,valuationMultiplier:12,urgencyMult:1.2},
          };

          const fmt  = n => '$' + Math.round(n).toLocaleString();
          const fmtK = n => { const v=Math.round(n); return v>=1000?'$'+(v/1000).toFixed(0)+'K':fmt(v); };
          const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
          const int=id=>parseInt(document.getElementById(id).value)||0;
          const flt=id=>parseFloat(document.getElementById(id).value)||0;

          function healthScore(d){
            const a=ARCH[d.arch],s=STAGES[d.stage],t=d.team;
            const eng=t.eng+t.devops, tot=t.pm+t.ux+t.eng+t.qa+t.devops+t.support;
            return clamp(Math.round(
              (1-a.debtRatio)*35 +
              Math.min((t.qa/Math.max(eng,1))/0.33,1)*20 +
              Math.min((t.devops/Math.max(tot,1))/0.15,1)*15 +
              (a.ci_cd?5:0) + a.testCoverage*5 +
              (Math.min((t.pm/Math.max(tot,1))/0.10,1)*.4+Math.min((t.ux/Math.max(tot,1))/0.10,1)*.3+Math.min((t.support/Math.max(tot,1))/0.10,1)*.3)*10 +
              (1-s.competitorRisk)*10
            ),0,100);
          }
          function grade(sc){
            if(sc>=90)return{g:'A+',c:'#00c853'};if(sc>=80)return{g:'A',c:'#00c853'};
            if(sc>=70)return{g:'B+',c:'#76d275'};if(sc>=60)return{g:'B',c:'#aeea00'};
            if(sc>=50)return{g:'C',c:'#ffd600'};if(sc>=40)return{g:'D',c:'#ff6d00'};
            if(sc>=30)return{g:'D-',c:'#dd2c00'};return{g:'F',c:'#b71c1c'};
          }
          function risk(sc){
            if(sc>=70)return{l:'Low',cl:'risk-low'};
            if(sc>=50)return{l:'Medium',cl:'risk-medium'};
            if(sc>=30)return{l:'High',cl:'risk-high'};
            return{l:'Critical',cl:'risk-critical'};
          }
          function financials(d){
            const a=ARCH[d.arch],s=STAGES[d.stage],burn=d.burn,rev=d.revenue||burn*.30;
            const bi=burn*a.maintenanceCost+burn*a.bugRate*.55;
            const dc=burn*a.velocityPenalty*s.urgencyMult*.75;
            const lo=rev*a.debtRatio*s.competitorRisk;
            const mo=bi+dc+lo,cp=1+a.debtRatio*.08,an=mo*12*cp;
            return{burnIneff:bi,delayCost:dc,lostOpp:lo,monthly:mo,annual:an,
                   refactor:burn*a.refactorMonths,security:120000*a.securityRisk,
                   valuation:an*s.valuationMultiplier*.5};
          }
          function benchmark(sc,stage){
            const B={seed:{p25:22,p50:38,p75:58},pre_series_a:{p25:28,p50:46,p75:63},series_a:{p25:38,p50:56,p75:72},series_b_plus:{p25:52,p50:68,p75:84}};
            const b=B[stage]||B.seed;
            let p;
            if(sc>=b.p75)p=75+((sc-b.p75)/(100-b.p75))*25;
            else if(sc>=b.p50)p=50+((sc-b.p50)/(b.p75-b.p50))*25;
            else if(sc>=b.p25)p=25+((sc-b.p25)/(b.p50-b.p25))*25;
            else p=(sc/Math.max(b.p25,1))*25;
            p=clamp(Math.round(p),1,99);
            return{percentile:p,bottom:100-p};
          }
          function traj(mo,ak){
            const r=ARCH[ak].debtRatio*.10;
            return Array.from({length:13},(_,i)=>Math.round(mo*Math.pow(1+r,i)));
          }

          let benchCh=null,trajCh=null;
          function drawBench(pct){
            const ctx=document.getElementById('benchDonut').getContext('2d');
            if(benchCh)benchCh.destroy();
            benchCh=new Chart(ctx,{type:'doughnut',data:{datasets:[{data:[pct,100-pct],backgroundColor:['#1565c0','#e0e0e0'],borderWidth:0}]},options:{cutout:'72%',plugins:{legend:{display:false},tooltip:{enabled:false}},animation:{duration:800}},plugins:[{id:'cl',beforeDraw(ch){const{ctx,chartArea:{left,top,right,bottom}}=ch;ctx.save();ctx.fillStyle='#1a237e';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(pct+'%',(left+right)/2,(top+bottom)/2);ctx.restore();}}]});
          }
          function drawTraj(data){
            const canvas=document.getElementById('trajChart'),ctx=canvas.getContext('2d');
            if(trajCh)trajCh.destroy();
            trajCh=new Chart(ctx,{type:'line',data:{labels:data.map((_,i)=>i),datasets:[{data,borderColor:'#ef5350',backgroundColor:'rgba(239,83,80,.08)',borderWidth:2,pointRadius:0,fill:true,tension:.4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:false}},scales:{x:{display:false},y:{display:false}},animation:{duration:800}}});
          }

          function buildAuditSections(d,fin,hs){
            const a=ARCH[d.arch],s=STAGES[d.stage],t=d.team;
            const tot=Object.values(t).reduce((x,y)=>x+y,0);
            const g=grade(hs),r=risk(hs),eng=t.eng+t.devops;
            const qaR=((t.qa/Math.max(eng,1))*100).toFixed(0);
            const dvR=((t.devops/Math.max(tot,1))*100).toFixed(0);
            return[
              {title:'📋 Executive Summary',body:`Grade ${g.g}, Health Score ${hs}/100, Risk: ${r.l}. Monthly Cost of Delay: ${fmt(fin.monthly)}, annualised: ${fmt(fin.annual)}.`},
              {title:'🏗️ Technical Debt Analysis',body:`Debt ratio: ${Math.round(a.debtRatio*100)}%. Bug rate: ${Math.round(a.bugRate*100)}%. Maintenance overhead: ${Math.round(a.maintenanceCost*100)}%. Velocity penalty: ${Math.round(a.velocityPenalty*100)}%. Scalability limit: ${a.scalabilityLimit}×. CI/CD: ${a.ci_cd?'✅':'⚠️ Missing'}. Refactor now: ${fmt(fin.refactor)}.`},
              {title:'👥 Team Efficiency',body:`QA ratio: ${qaR}% ${parseInt(qaR)<25?'⚠️ Low':'✅'}. DevOps: ${dvR}% ${parseInt(dvR)<10?'⚠️ Low':'✅'}. UX: ${t.ux===0?'⚠️ None':'✅'}. Support: ${t.support===0?'⚠️ None':'✅'}.`},
              {title:'💰 Financial Breakdown',body:`
CategoryMonthlyAnnual
Burn Inefficiency${fmt(fin.burnIneff)}${fmt(fin.burnIneff*12)}
Delay Cost${fmt(fin.delayCost)}${fmt(fin.delayCost*12)}
Lost Opportunity${fmt(fin.lostOpp)}${fmt(fin.lostOpp*12)}
Total COD${fmt(fin.monthly)}${fmt(fin.annual)}`},
              {title:'⚠️ Risks & Recommendations',body:(()=>{const rs=[];if(a.debtRatio>.5)rs.push('🔴 Codebase collapse risk — high debt ratio');if(t.qa===0)rs.push('🔴 No QA — defects ship to production');if(!a.ci_cd)rs.push('🟠 No CI/CD — deploy risk');if(t.devops===0)rs.push('🟠 No DevOps — manual deploy paralysis');rs.push('✅ Book a SaaS Execution Audit to reduce Cost of Delay by 62% in 90 days');return''+rs.map(x=>'
'+x+'').join('')+'';})()},
            ];
          }

          function buildAccordion(secs){
            const c=document.getElementById('accordionContainer');c.innerHTML='';
            secs.forEach((s,i)=>{
              const w=document.createElement('div');w.className='sc-accordion';
              const h=document.createElement('button');h.className='sc-acc-header';h.innerHTML=s.title+'▼';
              const b=document.createElement('div');b.className='sc-acc-body';b.innerHTML=s.body;
              if(i===0){h.classList.add('open');b.classList.add('open');}
              h.addEventListener('click',()=>{h.classList.toggle('open');b.classList.toggle('open');});
              w.append(h,b);c.appendChild(w);
            });
          }

          function validate(){
            let ok=true;
            const em=document.getElementById('fEmail').value.trim();
            const bn=flt('fBurn');
            const ws=document.getElementById('fWebsite').value.trim();
            const se=(id,show)=>{const el=document.getElementById(id);el.style.display=show?'block':'none';if(show)ok=false;};
            if(!em){document.getElementById('errEmail').textContent='Email is required';se('errEmail',true);}
            else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)){document.getElementById('errEmail').textContent='Invalid email';se('errEmail',true);}
            else se('errEmail',false);
            if(bn<=0){se('errBurn',true);}else se('errBurn',false);
            if(ws && !/^https?:\/\//i.test(ws)){se('errWebsite',true);}else se('errWebsite',false);
            return ok;
          }

          document.querySelectorAll('.sc-spin-btn').forEach(btn=>{
            btn.addEventListener('click',()=>{
              const inp=document.getElementById(btn.dataset.target);
              inp.value=Math.max(0,(parseInt(inp.value)||0)+parseInt(btn.dataset.dir));
            });
          });

          document.getElementById('calcBtn').addEventListener('click',()=>{
            if(!validate())return;
            const d={arch:document.getElementById('fArch').value,stage:document.getElementById('fStage').value,burn:flt('fBurn'),revenue:flt('fRevenue'),website:document.getElementById('fWebsite').value.trim(),email:document.getElementById('fEmail').value.trim(),team:{pm:int('fPM'),ux:int('fUX'),eng:int('fEng'),qa:int('fQA'),devops:int('fDevOps'),support:int('fSupport')}};
            const hs=healthScore(d),g=grade(hs),r=risk(hs),fin=financials(d),bm=benchmark(hs,d.stage),tr=traj(fin.monthly,d.arch);
            document.getElementById('riskBadge').textContent='Risk Level: '+r.l;
            document.getElementById('riskBadge').className='sc-risk-badge '+r.cl;
            document.getElementById('rCOD').textContent=fmt(fin.monthly);
            document.getElementById('rHealthScore').textContent=hs+'/100';
            const gEl=document.getElementById('rGrade');gEl.textContent=g.g;gEl.style.color=g.c;
            const pf=document.getElementById('progFill');pf.style.background=g.c;setTimeout(()=>{pf.style.width=hs+'%';},50);
            document.getElementById('rBurnIneff').textContent=fmtK(fin.burnIneff);
            document.getElementById('rDelayCost').textContent=fmtK(fin.delayCost);
            document.getElementById('rLostOpp').textContent=fmtK(fin.lostOpp);
            document.getElementById('rAnnualCOD').textContent=fmt(fin.annual);
            document.getElementById('rRefactor').textContent=fmt(fin.refactor);
            document.getElementById('rSecurity').textContent=fmt(fin.security);
            document.getElementById('rValuation').textContent=fmt(fin.valuation);
            drawBench(bm.percentile);
            document.getElementById('rBenchText').innerHTML='You are in the bottom '+bm.bottom+'% of '+STAGES[d.stage].label+' startups.
Your efficiency is lower than '+bm.bottom+'% of scaling companies.';
            drawTraj(tr);
            document.getElementById('emptyState').style.display='none';
            document.getElementById('resContent').style.display='block';
            window._lastAudit={d,fin,hs};
            try{const ls=JSON.parse(localStorage.getItem('saas_calc_leads')||'[]');ls.push({...d,timestamp:new Date().toISOString()});localStorage.setItem('saas_calc_leads',JSON.stringify(ls));}catch(_){}
          });

          document.getElementById('openAuditBtn').addEventListener('click',()=>{
            if(!window._lastAudit)return;
            const{d,fin,hs}=window._lastAudit,g=grade(hs),r=risk(hs);
            document.getElementById('modalSub').textContent='Health Score '+hs+'/100 · Grade '+g.g+' · Risk: '+r.l+' · Monthly COD: '+fmt(fin.monthly);
            buildAccordion(buildAuditSections(d,fin,hs));
            document.getElementById('leadOk').style.display='none';
            document.getElementById('leadSubmit').style.display='block';
            document.getElementById('auditOverlay').classList.add('active');
          });
          document.getElementById('closeModal').addEventListener('click',()=>document.getElementById('auditOverlay').classList.remove('active'));
          document.getElementById('auditOverlay').addEventListener('click',e=>{if(e.target===document.getElementById('auditOverlay'))document.getElementById('auditOverlay').classList.remove('active');});
          document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('auditOverlay').classList.remove('active');});

          document.getElementById('leadSubmit').addEventListener('click',()=>{
            const name=document.getElementById('lfName').value.trim();
            if(!name){alert('Please enter your name.');return;}
            const{d,fin,hs}=window._lastAudit||{};
            const g=grade(hs||0),r=risk(hs||0);
            const payload={name,phone:document.getElementById('lfPhone').value.trim(),company:document.getElementById('lfCompany').value.trim(),role:document.getElementById('lfRole').value.trim(),challenge:document.getElementById('lfChallenge').value.trim(),email:d?.email||'',website:d?.website||'',calculatorData:d,auditResults:{healthScore:hs,grade:g.g,risk:r.l,monthlyCOD:fin?.monthly,annualCOD:fin?.annual,burnIneff:fin?.burnIneff,delayCost:fin?.delayCost,lostOpp:fin?.lostOpp,refactorCost:fin?.refactor,securityRisk:fin?.security,valuationAtRisk:fin?.valuation},timestamp:new Date().toISOString(),source:'saas_audit_calculator'};
            fetch('/saas-calculator/submit-lead',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).catch(()=>{});
            try{const ls=JSON.parse(localStorage.getItem('saas_calc_leads_full')||'[]');ls.push(payload);localStorage.setItem('saas_calc_leads_full',JSON.stringify(ls));}catch(_){}
            document.getElementById('leadSubmit').style.display='none';
            document.getElementById('leadOk').style.display='block';
            const t=document.getElementById('toast');t.textContent='✅ Lead captured! We\'ll be in touch within 24 hours.';t.classList.add('sc-toast-show');setTimeout(()=>t.classList.remove('sc-toast-show'),4000);
          });
        })();
